function asHotelHTML(h,i){const st=h.stars?'★'.repeat(Math.min(5,Math.round(h.stars))):'';const img=h.image?` style="background-image:url('${escapeHTML(h.image)}')"`:'';return `<div class="as-hotel ${AS.hotel?.id===h.id?'sel':''}"><div class="as-photo"${img}>${h.image?'':'🏨'}${i===0?'<span>Popular</span>':''}</div><div style="min-width:0"><div class="as-hname">${escapeHTML(h.name)}</div>${st?`<div class="as-stars" aria-label="${h.stars} stars">${st}</div>`:''}<div class="mini">${h.rating?`Guest rating ${h.rating}/10 · `:''}${asHotelDist(h)}${h.address?' · '+escapeHTML(h.address):''}</div>${h.facilities?.length?`<div class="as-fac">${h.facilities.slice(0,6).map(k=>`<span>${escapeHTML(AS_FAC[k]||k)}</span>`).join('')}</div>`:''}<div class="as-from">${h.price?`<div><span class="mini">From</span><br><b>${asFmtMoney(h.price.total,h.price.currency)}</b> <span class="mini">total stay</span><div class="mini">${escapeHTML([h.price.board,h.price.refundable?(h.price.cancelBy?'Free cancellation until '+asDay(h.price.cancelBy.slice(0,10)):'Refundable'):'Non-refundable',h.price.taxesDue?'+ '+asFmtMoney(h.price.taxesDue,h.price.currency)+' taxes paid at hotel':''].filter(Boolean).join(' · '))}</div></div>`:`<div class="mini">${h.available===false?'No rooms for these dates':'Price &amp; availability: connect live rates'}</div>`}<button type="button" class="as-btn" data-as-hotel="${i}">${AS.hotel?.id===h.id?'Selected ✓':h.price?'Book Hotel':'Select'}</button></div></div></div>`}
const asBreakfast=r=>/breakfast|half board|full board|all inclusive|\b(BB|HB|FB|AI)\b/i.test(r?.board||'')&&!/room only|no breakfast/i.test(r?.board||'');
function asHotelView(){const f={b:$('asHfBreakfast')?.checked,c:$('asHfFree')?.checked,p:+($('asHfPrice')?.value||0),d:+($('asHfDist')?.value||0),s:$('asHfSort')?.value||'price',st:+($('asHfStars')?.value||0),fa:$('asHfFac')?.value||''},any=f.b||f.c||f.p,ok=r=>r&&(!f.b||asBreakfast(r))&&(!f.c||r.refundable)&&(!f.p||r.total<=f.p);const list=AS.hotels.map(h=>{if(!any)return h;const r=(h.rooms?.length?h.rooms:[h.price]).find(ok);return r?{...h,price:r}:null}).filter(h=>h&&(!f.d||h.distance<=f.d)&&(!f.st||(h.stars||0)>=f.st)&&(!f.fa||(h.facilities||[]).includes(f.fa)));const by={price:(a,b)=>(!!b.price-!!a.price)||((a.price?.total??1e12)-(b.price?.total??1e12))||a.distance-b.distance,dist:(a,b)=>a.distance-b.distance,rating:(a,b)=>((b.rating||0)-(a.rating||0))||((b.stars||0)-(a.stars||0))}[f.s]||(()=>0);return list.sort(by)}
function asRenderHotels(){const all=asHotelView();AS.hview=AS.showAll?all:all.slice(0,4);($('asHotelList')||$('asHotels')).innerHTML=AS.hview.length?AS.hview.map(asHotelHTML).join(''):`<div class="empty">${AS.hotels.length?'No hotels match these filters. Clear a filter to see more.':'No hotels found near this destination.'}</div>`;$('asHotelsAll').hidden=all.length<=4;$('asHotelsAll').textContent=AS.showAll?'Show less':`View All (${all.length})`}
const asPaxCount=q=>q?(+q.pax||1)+(+q.children||0)+(+q.infants||0):1;
function asFlightParams(q,shift=0){const add=(d,n)=>asIso(new Date(Date.parse(d)+n*864e5));const base={adults:q.pax,children:q.children||0,infants:q.infants||0,cabin:q.cabin||'economy',currency:'GBP'};if(q.trip==='multi')return new URLSearchParams({...base,legs:[{from:AS.fromCode,to:AS.toCode||AS.airport.iata,date:q.depart},...q.legs.map(l=>({from:l.fromCode,to:l.toCode,date:l.date}))].map(l=>`${l.from}:${l.to}:${l.date}`).join(',')});return new URLSearchParams({...base,from:AS.fromCode,to:AS.toCode||AS.airport.iata,depart:add(q.depart,shift),...(q.trip==='return'&&q.ret?{return:add(q.ret,shift)}:{})})}
const asDepHour=o=>+String(o.slices?.[0]?.departing||'').slice(11,13);
const asStops=o=>Math.max(0,...(o.slices||[]).map(s=>+s.stops||0));
