function asSelectFlight(i){const o=AS.offers[i];if(!o)return;AS.flight=o;AS.airport=AS.to?.airports?.find(a=>a.iata===o.slices[0]?.to)||AS.airport;asRenderFlights();asTrip();asReview('flight');if(AS.hotels.length)asRenderHotels();const nr=$('asReview').querySelector('.as-near');if(nr&&AS.hotel)nr.outerHTML=asHotelNearHTML(AS.hotel);asLoadTransfers(AS.seq);asStatus('ok',`Flight selected: ${o.airline} ${o.slices[0].from} → ${o.slices[0].to}. Book it on its own below; hotels in ${asCity(AS.to)} are optional suggestions.`);$('asFReview').scrollIntoView({behavior:'smooth',block:'start'})}
