function setupFinance(){$('fxBase').value='GBP';$('fxTarget').value='USD';$('fxFetch').onclick=async()=>{const base=$('fxBase').value,target=$('fxTarget').value,amount=Number($('fxAmount').value),out=$('fxOutput');if(!Number.isFinite(amount)||amount<0){out.textContent='Enter a valid amount.';return}if(base===target){out.textContent=`${amount} ${base} = ${amount} ${target}`;return}out.textContent='Loading public reference rate…';try{const response=await fetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(base)}&symbols=${encodeURIComponent(target)}`,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('Currency pair unavailable');const data=await response.json(),rate=data.rates?.[target];if(!Number.isFinite(rate))throw new Error('Currency pair unavailable');out.textContent=`${new Intl.NumberFormat('en-GB',{maximumFractionDigits:4}).format(amount)} ${base} ≈ ${new Intl.NumberFormat('en-GB',{maximumFractionDigits:4}).format(amount*rate)} ${target}\n1 ${base} ≈ ${rate} ${target}\nReference date: ${data.date||'not provided'}`}catch(err){out.textContent=`Could not load this rate. ${err.message}. Try GBP, EUR or USD, and check internet access.`}}}
