function emCountryBox(code){if(!code)return '<p class="mini" style="margin:0">Choose a country to see its police, ambulance and fire numbers.</p>';const nums=emNumbersFor(code),name=EM_DB?.countries?.[String(code).toUpperCase()]?.name||String(code).toUpperCase();return nums?`<p class="mini" style="width:100%;margin:0"><b>${escapeHTML(name)}</b> · tap a number to call</p>${nums.map(emCallHTML).join('')}${EM_EU112.includes(String(code).toUpperCase())?'<p class="mini" style="width:100%;margin:4px 0 0">🇪🇺 <b>112</b> also works free of charge from any mobile or landline everywhere in the EU, Iceland, Liechtenstein and Norway.</p>':''}${emSourceHTML()}`:`<div class="item" style="display:flex;gap:10px;align-items:center;padding:6px 0"><i class="em-dot grey"></i><span class="mini">Emergency number for ${escapeHTML(name)} is not verified in Aiva. Check official travel advice before you need it.</span></div>${emLink('https://www.gov.uk/foreign-travel-advice','Official travel advice')}`}
async function emSetupCountry(){await emLoadNumbers();const sel=$('emCountry');if(sel&&EM_DB){sel.innerHTML=emCountryOpts(localStorage.getItem('aiva-em-country')||(navigator.language||'').split('-')[1]||'','Choose a country');const show=()=>{$('emCountryNums').innerHTML=emCountryBox(sel.value);localStorage.setItem('aiva-em-country',sel.value)};sel.onchange=show;show();const find=$('emCountryFind');if(find)find.oninput=()=>{const n=x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),t=n(find.value.trim());if(t.length<2)return;const all=Object.entries(EM_DB.countries),alias=EM_ALIAS[t],hit=all.find(([c])=>c.toLowerCase()===t||c===alias)||all.find(([,v])=>n(v.name).startsWith(t))||all.find(([,v])=>n(v.name).includes(t));if(!hit){sel.value='';$('emCountryNums').innerHTML=`<p class="mini" style="margin:0">No country matches “${escapeHTML(find.value.trim())}”. Try another spelling or choose from the list.</p>`;return}if(sel.value!==hit[0]){sel.value=hit[0];show()}}}asSosRender();if(em.place)emRenderWhere()}
function asSosRender(code){const sel=$('asSosCountry');if(!sel||!EM_DB)return;const k=String(code||sel.value||AS.to?.countryCode||(navigator.language||'').split('-')[1]||'').toUpperCase();if(!sel.options.length)sel.innerHTML=emCountryOpts(k,'Choose a country');if(EM_DB.countries[k])sel.value=k;$('asSosNums').innerHTML=emCountryBox(sel.value);const dest=AS.to&&sel.value&&sel.value===String(AS.to.countryCode||'').toUpperCase();$('asSosMeta').textContent=dest?'Destination: '+asCity(AS.to):'Works without a booking'}
const em={place:null,cat:'health',seq:0,tseq:0};const emColor=s=>({open:'green',live:'green',ok:'green',closed:'red',none:'red',disrupted:'red'}[s]||'grey');const emDist=m=>m<1000?`${m} m`:`${(m/1000).toFixed(m<10000?1:0)} km`;const emLink=(url,label,cls='light')=>`<a class="btn ${cls}" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;function emStatus(kind,msg){const el=$('emStatus');if(!msg){el.hidden=true;return}el.hidden=false;el.className='voice-status '+kind;el.innerHTML='<span class="dot" aria-hidden="true"></span><span></span>';el.lastChild.textContent=msg}async function emGet(path){const res=await fetch(path,{signal:AbortSignal.timeout(45000)});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Service unavailable. Please try again.');return data}function emRenderWhere(){const p=em.place,nums=emNumbersFor(p.countryCode);$('emWhere').hidden=false;$('emWhere').innerHTML=`📍 ${escapeHTML(p.label||'Selected location')}<small>${p.gps?'Your current location':'Searched location'} · ${p.lat.toFixed(4)}, ${p.lon.toFixed(4)}</small>`;const box=$('emNumbers');box.hidden=false;box.innerHTML=(nums?(p.gps?'':'<p class="mini" style="width:100%;margin:0">Numbers for the searched place. Dial them when you are there; your phone calls the network it is on now.</p>')+nums.map(emCallHTML).join('')+emSourceHTML():`<div class="item" style="display:flex;gap:10px;align-items:center;padding:6px 0"><i class="em-dot grey"></i><span class="mini">Emergency number for this country is not verified in Aiva. Check official travel advice before you need it.</span></div>${emLink('https://www.gov.uk/foreign-travel-advice','Official travel advice')}`)+(p.gps?'<button class="btn light" type="button" id="emShare">📤 Share my location</button>':'');const share=$('emShare');if(share)share.onclick=async()=>{const url=`${location.origin}/?aivaMap=${p.lat},${p.lon}`;try{if(navigator.share){await navigator.share({title:'My location',text:'This is my current location:',url});return}await navigator.clipboard.writeText(url);emStatus('ok','Location link copied. Paste it into a message to a trusted contact.')}catch(err){if(err?.name!=='AbortError')emStatus('error','Could not share automatically. Location link: '+url)}}}async function emSetPlace(place){em.place=place;emRenderWhere();emStatus('',null);$('emTransportRefresh').disabled=false;emLoadTransport();emLoadPlaces()}function emLocate(){if(!navigator.geolocation){emStatus('error','Location is not available in this browser. Search for a place instead.');return}emStatus('busy','Finding your location…');navigator.geolocation.getCurrentPosition(async pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;let info={label:'',countryCode:''};try{info=await emGet(`/api/emergency/geocode?lat=${lat}&lon=${lon}`)}catch{}emSetPlace({lat,lon,label:info.label||'Your location',countryCode:info.countryCode||'',gps:true})},err=>emStatus('error',err.code===1?'Location access is blocked. Allow location for Aiva in your browser settings, or search for a place instead.':'Your location could not be found. Search for a place instead.'),{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}async function emSearch(){const q=$('emQuery').value.trim();if(!q){emStatus('error','Type a town, street or postcode, or tap Use my location.');return}emStatus('busy','Searching…');try{const r=await emGet('/api/emergency/geocode?q='+encodeURIComponent(q));emSetPlace({...r,gps:false})}catch(err){emStatus('error',err.message)}}function emQS(){const p=em.place;return `lat=${p.lat}&lon=${p.lon}&cc=${encodeURIComponent(p.countryCode||'')}&gps=${p.gps?1:0}&tz=${encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone||'')}`}async function emLoadTransport(){if(!em.place)return;const seq=++em.tseq,box=$('emTransport');box.innerHTML='<div class="empty">Loading live transport…</div>';$('emTransportSource').textContent='';try{const d=await emGet('/api/emergency/transport?'+emQS());if(seq!==em.tseq)return;box.innerHTML=d.stops.length?d.stops.map(emStopHTML).join(''):'<div class="empty">No stations or stops found within 1 km.</div>';$('emTransportSource').textContent=`${d.live?'Live data':'Station and stop locations'}: ${d.source} · updated ${new Date(d.retrieved).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`+(d.live?'':' · Live times are not available in Aiva for this area yet. Use the official links for live times.')}catch(err){if(seq===em.tseq)box.innerHTML=`<div class="item"><i class="em-dot grey"></i><div class="em-body">${escapeHTML(err.message)}</div></div>`}}function emStopHTML(s){const c=emColor(s.state),modes={bus:'🚌',tube:'🚇',tram:'🚊',dlr:'🚈',overground:'🚆','elizabeth-line':'🚆','national-rail':'🚆',train:'🚆',ferry:'⛴️'};const deps=s.departures.length?`<ul class="em-deps">${s.departures.slice(0,5).map(d=>`<li><span><b>${escapeHTML(d.line)}</b> → ${escapeHTML(d.destination)}${d.platform?` <span class="mini">· ${escapeHTML(d.platform)}</span>`:''}${d.status?` <span class="mini ${d.cancelled?'em-state red':''}">· ${escapeHTML(d.status)}</span>`:''}${d.realtime===false?' <span class="mini">· timetabled</span>':''}</span><b class="${d.cancelled?'em-state red':''}">${d.cancelled?'Cancelled':d.unknownTime?(/^Delayed/.test(d.status)?'Delayed':'No estimate'):d.minutes?d.minutes+' min':'Due'}</b></li>`).join('')}</ul>`:'';const lines=s.lines.length?`<div class="em-lines">${s.lines.map(l=>`<button type="button" class="em-line" ${s.timetable?`data-em-tt="${escapeHTML(l.id)}" data-em-stop="${escapeHTML(s.id)}" title="Show first and last services"`:''}><i class="em-dot ${emColor(l.state)}"></i>${escapeHTML(l.name)} · ${escapeHTML(l.status)}</button>`).join('')}</div>`:'';const reasons=[...new Set([...s.lines.filter(l=>l.reason&&l.state!=='ok').map(l=>l.reason),...(s.alerts||[])])].slice(0,2).map(r=>`<div class="em-reason">⚠️ ${escapeHTML(r)}</div>`).join('');return `<div class="item"><i class="em-dot ${c}"></i><div class="em-body"><div class="item-title">${(s.modes.map(m=>modes[m]).find(Boolean))||'🚏'} ${escapeHTML(s.name)}${s.indicator?` <span class="mini">${escapeHTML(s.indicator)}</span>`:''}</div><div class="mini">${emDist(s.distance)} away</div><div class="em-state ${c}">${escapeHTML(s.label)}</div>${deps}${lines}${reasons}${s.timetable?'<div class="em-tt" data-em-ttout></div>':''}<div class="em-links">${aivaDirectionsButton(s,em.place)}${(s.links||[]).map(l=>emLink(l.url,escapeHTML(l.label))).join('')}</div></div></div>`}async function emTimetable(btn){const out=btn.closest('.em-body').querySelector('[data-em-ttout]');if(!out)return;out.textContent='Loading today\'s first and last services…';try{const d=await emGet(`/api/emergency/timetable?line=${encodeURIComponent(btn.dataset.emTt)}&stop=${encodeURIComponent(btn.dataset.emStop)}`);out.innerHTML=d.directions.map(x=>`<div>🕐 <b>${escapeHTML(d.line.toUpperCase())}</b>${x.towards?' '+escapeHTML(x.towards):''}: ${x.schedule?(x.runs24h?'<b>Runs 24 hours today</b>':`first ${escapeHTML(x.first)} · last ${escapeHTML(x.last)}`)+` <span>(${escapeHTML(x.schedule)} timetable)</span>`:'no timetable published for today'}</div>`).join('')+'<div>Scheduled times from TfL; check live departures above for changes.</div>'}catch(err){out.textContent=err.message}}function emBookingURL(p){const day=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};return `https://www.booking.com/searchresults.html?ss=${encodeURIComponent([p.name,p.city].filter(Boolean).join(', '))}&checkin=${day(0)}&checkout=${day(1)}&group_adults=1&no_rooms=1`}function emPlaceHTML(p){const c=emColor(p.status.state),stay=em.cat==='stay'&&p.kind!=='Emergency shelter';const links=[aivaDirectionsButton(p,em.place)];if(p.phone)links.push(emLink('tel:'+p.phone.split(/[;,]/)[0].replace(/[^\d+]/g,''),'📞 Call'));if(stay)links.push(emLink(emBookingURL(p),'Check price &amp; availability'));if(p.website&&/^https?:\/\//.test(p.website))links.push(emLink(p.website,'Website'));return `<div class="item"><i class="em-dot ${c}"></i><div class="em-body"><div class="item-title">${escapeHTML(p.name)}</div><div class="mini">${escapeHTML(p.kind)}${p.emergency?' · <b style="color:#b42335">Emergency department (A&amp;E) listed</b>':''} · ${emDist(p.distance)} away${p.address?' · '+escapeHTML(p.address):''}</div><div class="em-state ${c}">${escapeHTML(p.status.label)}</div>${p.openingHours&&p.status.state!=='unknown'?`<div class="mini">Listed hours: ${escapeHTML(p.openingHours)}${p.checked?` · checked ${escapeHTML(p.checked)}`:''}</div>`:''}${stay?'<div class="mini">Price and availability: not verified in Aiva</div>':''}<div class="em-links">${links.join('')}</div></div></div>`}async function emLoadPlaces(){if(!em.place)return;const seq=++em.seq,box=$('emPlaces');$('emStay').hidden=em.cat!=='stay';box.innerHTML='<div class="empty">Loading nearby services…</div>';$('emPlacesSource').textContent='';try{const d=await emGet(`/api/emergency/places?${emQS()}&category=${em.cat}&radius=${$('emRadius').value}`);if(seq!==em.seq)return;let extra='';if(em.cat==='stay'&&em.place.countryCode==='gb')extra=`<div class="item"><i class="em-dot grey"></i><div class="em-body"><div class="item-title">Homeless or at risk tonight (UK)</div><div class="mini">Your local council must help with emergency housing. Shelter's free helpline gives urgent advice.</div><div class="em-links">${emLink('https://www.gov.uk/find-local-council','Find your local council')}${emLink('tel:08088004444','📞 Shelter 0808 800 4444')}</div></div></div>`;box.innerHTML=extra+(d.places.length?d.places.map(emPlaceHTML).join(''):'<div class="empty">Nothing of this type is listed nearby. Try a larger search distance.</div>');$('emPlacesSource').textContent=`Source: ${d.source} · ${d.localTimeKnown?'open/closed shown in local time ('+d.timeZone+')':'local time zone unknown, so open/closed is not verified'} · updated ${new Date(d.retrieved).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`}catch(err){if(seq===em.seq)box.innerHTML=`<div class="item"><i class="em-dot grey"></i><div class="em-body">${escapeHTML(err.message)}</div></div>`}}function setupEmergency(){$('emLocate').onclick=emLocate;$('emSearch').onclick=emSearch;$('emQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();emSearch()}});$('emRadius').onchange=emLoadPlaces;$('emTransportRefresh').onclick=emLoadTransport;document.querySelectorAll('[data-em-cat]').forEach(b=>b.onclick=()=>{em.cat=b.dataset.emCat;document.querySelectorAll('[data-em-cat]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});emLoadPlaces()});$('emTransport').addEventListener('click',e=>{const b=e.target.closest('[data-em-tt]');if(b)emTimetable(b)})}setupNav();setupTrade();setupTranslation();setupCalculator();setupTravel();setupFinance();setupSettings();setupEmergency();$('year').textContent=new Date().getFullYear();if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
